from dateutil import parser as dparser

def parse_date_safe(s):
    if not s or not isinstance(s, str):
        return None
    try:
        return dparser.parse(s, fuzzy=True).date()
    except Exception:
        return None

# Parse grant date and filter to H2 2019
df_all['grant_dt'] = df_all['grant_date'].map(parse_date_safe)
import datetime as dt
cohort_mask = df_all['grant_dt'].between(dt.date(2019,7,1), dt.date(2019,12,31))
df_cohort = df_all[cohort_mask].copy()
print(df_cohort.shape)

import json
import re

def has_de_inventor(s):
    if not s or not isinstance(s, str):
        return False
    try:
        arr = json.loads(s)
        for inv in arr:
            if inv.get('country_code') == 'DE':
                return True
        return False
    except Exception:
        return False

df_cohort['de_inv'] = df_cohort['inventor_harmonized'].map(has_de_inventor)
print("DE cohort:", df_cohort['de_inv'].sum())
df_de = df_cohort[df_cohort['de_inv']].copy()
print(df_de.shape)
print(df_de[['Patents_info','grant_date','filing_date']].head(3))

# Parse CPC codes for cohort patents, build group_set
def parse_cpc(s):
    if not s or not isinstance(s, str):
        return []
    try:
        arr = json.loads(s)
        codes = [c.get('code') for c in arr if c.get('code')]
        return list(set(codes))
    except Exception:
        return []

df_de['cpc_codes'] = df_de['cpc'].map(parse_cpc)
all_codes = set()
for codes in df_de['cpc_codes']:
    all_codes.update(codes)
print("Distinct cohort CPC codes:", len(all_codes))
print(list(all_codes)[:20])

# Build dict: symbol -> (level, parents_list, titleFull)
cpc_dict = {}
for sym, lvl, parents_str, title in cpc_rows:
    try:
        plist = json.loads(parents_str) if parents_str else []
    except Exception:
        plist = []
    cpc_dict[sym] = (int(lvl) if lvl is not None else None, plist, title)

print(len(cpc_dict))
# Test a code
test_codes = ['C01B33/00', 'H01M10/0565', 'B29C70/48', 'C12N2310/20']
for c in test_codes:
    print(c, cpc_dict.get(c))

# Build mapping cpc -> level4 ancestor
def find_level4(code):
    if code not in cpc_dict:
        return None
    lvl, parents, title = cpc_dict[code]
    if lvl == 4:
        return code
    # check parents
    for p in parents:
        if p in cpc_dict and cpc_dict[p][0] == 4:
            return p
    # Fallback: try prefix matching - first 3 chars
    pref = code[:3]
    if pref in cpc_dict and cpc_dict[pref][0] == 4:
        return pref
    return None

cpc_to_l4 = {}
for c in all_codes:
    l4 = find_level4(c)
    cpc_to_l4[c] = l4

unmapped = [c for c,v in cpc_to_l4.items() if v is None]
print("Unmapped:", len(unmapped), unmapped[:20])
mapped_set = set(v for v in cpc_to_l4.values() if v)
print("Distinct level-4 groups in cohort:", len(mapped_set))
print(sorted(mapped_set))

# Parse all CPC fields
df_all_valid = df_all.dropna(subset=['filing_year']).copy()
df_all_valid['filing_year'] = df_all_valid['filing_year'].astype(int)
print(df_all_valid.shape)

# Build per-row set of level-4 codes
def cpc_to_level4_set(s):
    if not s or not isinstance(s, str):
        return set()
    try:
        arr = json.loads(s)
    except Exception:
        return set()
    res = set()
    for entry in arr:
        c = entry.get('code')
        if c:
            # level-4 is first 3 chars (verified above)
            l4 = c[:3]
            if l4 in cpc_dict and cpc_dict[l4][0] == 4:
                res.add(l4)
    return res

# This may be slow but only ~273k rows
import time
t0 = time.time()
df_all_valid['l4_set'] = df_all_valid['cpc'].map(cpc_to_level4_set)
print(time.time() - t0, "seconds")
print(df_all_valid['l4_set'].head())
